    {
      "Unexamined": {
        "author": "alice",
        "body": "If disabled users keep valid tokens for too long, the security team loses a practical way to contain account compromise.",
        "claim_id": "cond-revocation-gap"
      }
    },
    {
      "Unexamined": {
        "author": "dave",
        "body": "The admin dashboard is used only by employees in browsers, so cookie-based UX is acceptable there.",
        "claim_id": "fact-admin-browser-only"
      }
    },
    {
      "Unexamined": {
        "author": "bob",
        "body": "A third-party identity provider adds vendor cost, tenant setup overhead, and a migration burden for the team.",
        "claim_id": "fact-external-idp-cost"
      }
    },
    {
      "Unexamined": {
        "author": "alice",
        "body": "Self-issued JWTs are hard to revoke before expiry unless we also run a denylist or token introspection service.",
        "claim_id": "fact-jwt-revocation-hard"
      }
    },
    {
      "Unexamined": {
        "author": "dave",
        "body": "We do not have a low-latency shared session store across regions in the current platform.",
        "claim_id": "fact-no-shared-session-store"
      }
    },
    {
      "Unexamined": {
        "author": "bob",
        "body": "The public API already has a browser SPA client and the mobile app will need token-based access soon.",
        "claim_id": "fact-public-api-clients"
      }
    },
    {
      "Unexamined": {
        "author": "carol",
        "body": "Decide the authentication approach for the public API and the admin dashboard before beta.",
        "claim_id": "item-auth"
      }
    },
    {
      "Unexamined": {
        "author": "carol",
        "body": "External OIDC providers give us mature MFA, recovery, and federation flows that are expensive to reproduce internally.",
        "claim_id": "ref-oidc-practice"
      }
    },
    {
      "Unexamined": {
        "author": "alice",
        "body": "We should prefer an approach that lets us revoke compromised access quickly during incident response.",
        "claim_id": "value-fast-revocation"
      }
    }
  ],
